/**
 * 启动前自动生成 public/ 目录下所有文件
 * npm start 前自动运行（通过 prestart 钩子）
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PUBLIC_DIR = path.join(__dirname, 'public');

function ensureDir(dirPath) {
  if (!fs.existsSync(dirPath)) fs.mkdirSync(dirPath, { recursive: true });
}

function writeFile(relPath, base64Data) {
  const fullPath = path.join(PUBLIC_DIR, relPath);
  ensureDir(path.dirname(fullPath));
  fs.writeFileSync(fullPath, Buffer.from(base64Data, 'base64'));
}

/* 生成SVG头像 */
function generateAvatarSVG(index) {
  var colors = ['#FF6B9D','#FFB6C1','#FF8E72','#A8E6CF','#FFD93D','#6BCB77','#4D96FF','#9B59B6'];
  var color = colors[(index - 1) % colors.length];
  var initials = ['甜','暖','柔','笑','梦','星','月','花'][(index - 1) % 8];
  return '<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" viewBox="0 0 200 200">' +
    '<defs><radialGradient id="g' + index + '" cx="50%" cy="40%">' +
    '<stop offset="0%" stop-color="' + color + '" stop-opacity="0.95"/>' +
    '<stop offset="100%" stop-color="' + color + '" stop-opacity="0.6"/></radialGradient></defs>' +
    '<circle cx="100" cy="100" r="100" fill="url(#g' + index + ')"/>' +
    '<text x="100" y="125" font-size="80" text-anchor="middle" fill="#fff" font-family="sans-serif" font-weight="bold">' + initials + '</text></svg>';
}

console.log('=== Generating public/ directory ===');
ensureDir(PUBLIC_DIR);

/* 写入所有文本文件 */
const TEXT_FILES = [{"path":"admin.html","data":""},{"path":"css/mochi-chat.css","data":""},{"path":"forum-avatars-base64.js","data":""},{"path":"forum.js","data":""},{"path":"icons/mochi-phone-icon.svg","data":""},{"path":"index.html","data":""},{"path":"js/mochi-ai.js","data":""},{"path":"js/mochi-app.js","data":""},{"path":"js/mochi-core.js","data":""},{"path":"js/mochi-media.js","data":""},{"path":"js/mochi-settings.js","data":""},{"path":"js/mochi-social.js","data":""},{"path":"js/mochi-ui.js","data":""},{"path":"manifest.webmanifest","data":""},{"path":"novel-game.css","data":""},{"path":"novel-game.js","data":""},{"path":"profile.js","data":""}];
for (const file of TEXT_FILES) {
  writeFile(file.path, file.data);
  console.log('[generate] ' + file.path);
}

/* 生成SVG头像（保存为.png后缀，server.js按PNG读取） */
ensureDir(path.join(PUBLIC_DIR, 'avatars'));
for (let i = 1; i <= 8; i++) {
  var svgContent = generateAvatarSVG(i);
  var svgPath = path.join(PUBLIC_DIR, 'avatars', 'avatar' + i + '.svg');
  fs.writeFileSync(svgPath, svgContent, 'utf8');
  /* 同时写一份.png后缀的SVG内容，让server.js的loadEmbedFiles能读到 */
  var pngPath = path.join(PUBLIC_DIR, 'avatars', 'avatar' + i + '.png');
  fs.writeFileSync(pngPath, svgContent, 'utf8');
  console.log('[generate] avatars/avatar' + i + '.png (SVG placeholder)');
}

/* 生成qr-code.png占位 */
var qrSVG = '<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" viewBox="0 0 200 200">' +
  '<rect width="200" height="200" fill="#fff"/>' +
  '<rect x="20" y="20" width="60" height="60" fill="#333"/>' +
  '<rect x="120" y="20" width="60" height="60" fill="#333"/>' +
  '<rect x="20" y="120" width="60" height="60" fill="#333"/>' +
  '<rect x="90" y="90" width="20" height="20" fill="#333"/></svg>';
fs.writeFileSync(path.join(PUBLIC_DIR, 'qr-code.png'), qrSVG, 'utf8');
console.log('[generate] qr-code.png (SVG placeholder)');

console.log('=== Generated ' + (TEXT_FILES.length + 9) + ' files ===');
